CREATE TABLE IF NOT EXISTS servers(id SERIAL PRIMARY KEY,hostname VARCHAR(128) UNIQUE NOT NULL,environment VARCHAR(32) NOT NULL DEFAULT 'Production',team VARCHAR(64) NOT NULL DEFAULT 'Infrastructure',status VARCHAR(24) NOT NULL DEFAULT 'healthy',cpu_percent INTEGER NOT NULL DEFAULT 20,memory_percent INTEGER NOT NULL DEFAULT 35,disk_percent INTEGER NOT NULL DEFAULT 40,last_seen TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS incidents(id SERIAL PRIMARY KEY,incident_key VARCHAR(32) UNIQUE NOT NULL,source VARCHAR(32) NOT NULL DEFAULT 'manual',title VARCHAR(240) NOT NULL,host_name VARCHAR(128) NOT NULL,issue_type VARCHAR(64) NOT NULL DEFAULT 'Other',current_value VARCHAR(32) NOT NULL DEFAULT 'N/A',threshold VARCHAR(32) NOT NULL DEFAULT 'N/A',severity VARCHAR(24) NOT NULL DEFAULT 'warning',team VARCHAR(64) NOT NULL DEFAULT 'Infrastructure',status VARCHAR(24) NOT NULL DEFAULT 'open',summary TEXT NOT NULL DEFAULT '',detected_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS activity(id SERIAL PRIMARY KEY,incident_key VARCHAR(32) NOT NULL DEFAULT '',event VARCHAR(128) NOT NULL,detail VARCHAR(240) NOT NULL DEFAULT '',occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
